package com.gymmind.membership.domain.model;
import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="payment_record",uniqueConstraints=@UniqueConstraint(name="uk_payment_tenant_reference",columnNames={"tenant_id","reference"})) public class PaymentRecord extends TenantScopedEntity{ @Column(name="order_id",nullable=false)private Long orderId;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,length=128)private String reference;@Column(name="payment_method",nullable=false,length=32)private String paymentMethod;@Column(name="recorded_at",nullable=false)private Instant recordedAt;protected PaymentRecord(){}private PaymentRecord(Long t,Long o,BigDecimal a,String c,String r,String m){super(t);if(o==null||a==null||a.signum()<0||c==null||r==null||r.isBlank()||m==null||m.isBlank())throw new IllegalArgumentException("Invalid payment record");orderId=o;amount=a;currency=c.toUpperCase();reference=r.trim();paymentMethod=m.trim();recordedAt=Instant.now();}public static PaymentRecord create(Long t,Long o,BigDecimal a,String c,String r,String m){return new PaymentRecord(t,o,a,c,r,m);}public Long getOrderId(){return orderId;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getReference(){return reference;}public String getPaymentMethod(){return paymentMethod;}public Instant getRecordedAt(){return recordedAt;}}
